import { Link, NavLink, useNavigate } from 'react-router-dom';
import { useEffect, useRef, useState } from 'react';
import './Navbar.css';
import { productApi } from '../services/api';
import useDebounce from '../hooks/useDebounce';
import { useStore } from '../context/StoreContext';

function Navbar() {
  const navigate = useNavigate();
  const searchRef = useRef(null);
  const { cartCount, openAuth, darkMode, toggleTheme } = useStore();
  const [query, setQuery] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [open, setOpen] = useState(false);
  const debouncedQuery = useDebounce(query, 250);

  useEffect(() => {
    let active = true;
    if (!debouncedQuery.trim()) {
      setSuggestions([]);
      return undefined;
    }
    productApi
      .getSuggestions(debouncedQuery)
      .then((data) => active && setSuggestions(data.suggestions || []))
      .catch(() => active && setSuggestions([]));
    return () => {
      active = false;
    };
  }, [debouncedQuery]);

  useEffect(() => {
    const handler = (event) => {
      if (searchRef.current && !searchRef.current.contains(event.target)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const submit = (value = query) => {
    const cleaned = value.trim();
    if (!cleaned) return;
    setOpen(false);
    navigate(`/products?search=${encodeURIComponent(cleaned)}`);
  };

  return (
    <header className="navbar-wrap">
      <div className="navbar container">
        <Link className="brand" to="/" aria-label="Tech Store home">
          <span className="brand-icon">TS</span>
          <span>
            <strong>Tech Store</strong>
            <small>AI powered commerce</small>
          </span>
        </Link>

        <div className="nav-search" ref={searchRef}>
          <form onSubmit={(event) => { event.preventDefault(); submit(); }}>
            <span className="search-icon">⌕</span>
            <input
              value={query}
              onChange={(event) => { setQuery(event.target.value); setOpen(true); }}
              onFocus={() => setOpen(true)}
              placeholder="Search iPhone 17 Pro Max, RTX 5090, MacBook Pro M5..."
              aria-label="Search products"
            />
            <button type="submit">Search</button>
          </form>
          {open && suggestions.length > 0 && (
            <div className="suggestions" role="listbox">
              {suggestions.map((item) => (
                <button key={item} type="button" onClick={() => submit(item)}>
                  <span>⚡</span> {item}
                </button>
              ))}
            </div>
          )}
        </div>

        <nav className="nav-links" aria-label="Primary navigation">
          <NavLink to="/products">Products</NavLink>
          <NavLink to="/categories">Categories</NavLink>
          <NavLink to="/deals">Deals</NavLink>
          <NavLink to="/ai-recommendations">AI Picks</NavLink>
          <NavLink to="/dashboard">Dashboard</NavLink>
        </nav>

        <div className="nav-actions">
          <button className="icon-btn" onClick={toggleTheme} aria-label="Toggle theme">{darkMode ? '☀' : '🌙'}</button>
          <button className="login-btn" onClick={openAuth}>Login</button>
          <Link className="cart-btn" to="/cart" aria-label={`Cart with ${cartCount} items`}>🛒 <span>{cartCount}</span></Link>
        </div>
      </div>
    </header>
  );
}

export default Navbar;
